import fs from 'fs';
import path from 'path';

import {
  DEFAULT_METRICS,
  exactMatchMetric,
  lengthVarianceMetric,
  toxicityMetric
} from './metrics.js';
import { resolveReportPath, toJson, toMarkdown } from './reporters.js';

const defaultFs = fs;

const ensureArray = (value) => (Array.isArray(value) ? value : []);

export function loadDataset({ outputsPath, referencesPath, fs: fsModule = defaultFs } = {}) {
  if (!outputsPath) {
    throw new Error('outputsPath is required for evaluation.');
  }

  const outputsAbsolute = path.resolve(outputsPath);
  const outputsRaw = fsModule.readFileSync(outputsAbsolute, 'utf8');
  const outputs = JSON.parse(outputsRaw);

  let references = [];
  let referencesAbsolute = null;
  if (referencesPath) {
    referencesAbsolute = path.resolve(referencesPath);
    const referencesRaw = fsModule.readFileSync(referencesAbsolute, 'utf8');
    references = JSON.parse(referencesRaw);
  }

  return {
    outputs,
    references,
    outputsPath: outputsAbsolute,
    referencesPath: referencesAbsolute
  };
}

export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS
} = {}) {
  const outs = ensureArray(outputs);
  const refs = ensureArray(references);

  const evaluations = metrics.map((metric) => {
    if (typeof metric === 'function') {
      return metric(outs, refs);
    }
    if (metric && typeof metric.evaluate === 'function') {
      return metric.evaluate(outs, refs);
    }
    throw new Error('Invalid metric supplied to runEvaluations.');
  });

  return evaluations;
}

function parseThreshold(thresholdStr) {
  const match = thresholdStr.match(/^([a-zA-Z0-9_-]+)=(\d+(?:\.\d+)?)$/);
  if (!match) {
    return { error: 'format' };
  }
  const [, metricId, minStr] = match;
  const min = Number.parseFloat(minStr);
  if (Number.isNaN(min)) {
    return { error: 'format' };
  }
  if (min < 0 || min > 1) {
    return { error: 'range', metricId, value: min };
  }
  return { metricId, min };
}

export function validateThresholds(thresholdStrs, evaluations) {
  if (!thresholdStrs || !Array.isArray(thresholdStrs)) {
    return { valid: true, errors: [], thresholds: [] };
  }

  const errors = [];
  const thresholds = [];
  const knownMetricIds = evaluations.map((e) => e.id);

  for (const thresholdStr of thresholdStrs) {
    const parsed = parseThreshold(thresholdStr);
    if (!parsed) {
      errors.push(`Malformed threshold: ${thresholdStr}. Expected format: <metric>=<number>`);
      continue;
    }
    const { metricId, min } = parsed;
    if (!knownMetricIds.includes(metricId)) {
      errors.push(`Unknown metric: ${metricId}. Valid metrics: ${knownMetricIds.join(', ')}`);
      continue;
    }
    thresholds.push({ metricId, min });
  }

  return {
    valid: errors.length === 0,
    errors,
    thresholds
  };
}

function checkThresholds(thresholds, evaluations) {
  const results = [];
  for (const { metricId, min } of thresholds) {
    const metric = evaluations.find((e) => e.id === metricId);
    const score = metric?.score ?? null;
    const passed = score !== null && score >= min;
    results.push({
      metric: metricId,
      min,
      score,
      passed
    });
  }
  return results;
}

export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Array.isArray(thresholds) && thresholds.length > 0) {
    const thresholdResults = checkThresholds(thresholds, evaluations);
    const passed = thresholdResults.every((r) => r.passed);
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

